// ВРУЧНУЮ (не автоматизируется — нужен новый аккаунт, создание аккаунтов в автотестах не делаем): п.1 S-08 и ветка «с достижением».
// Кейс: .qa/tests/readiness/TX-01-texts-as-figma.md (п.1–4).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byLabel, tapLabel, tapText, scrollToText } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { homeDates, tryDeleteDate } from '../_lib/app-1310b.ts';
import { addImportantDateToday } from '../_lib/app-1410.ts';
import {
  goHome, openProfile, counter, newestRecentPrayer, openCatalogPrayer, tapFinish, recordAllowed, button,
  REPEAT_AGAIN, FINISH_TITLE, BACK_HOME, nodes,
} from '../_lib/readiness-1910.ts';
import { isoDate } from '../../../e2e/tests/_helpers/dates.ts';

const QA_DATE = 'QA-AUTO-תאריך 2110';

describe('21.10 — тексты как в Figma (#32d78d)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('TX-01a Главная «+» → «תאריך חשוב»: заголовок окна «תאריך חדש» (S-29), «אזכרה» — «אזכרה»; правка сохранённой даты — «עריכת תאריך»; чип на главной остаётся «תאריך חשוב» #32d78d #00542c25 @data', async () => {
    try {
      // Новая дата: заголовок «תאריך חדש», старого «תאריך חשוב» как заголовка окна нет.
      await homeDates();
      await tapLabel('הוספת תאריך חשוב');
      await expect(byText('תאריך חשוב')).toBeExisting();          // чип выбора типа — без изменений (решение 19.10)
      await tapText('תאריך חשוב');
      await expect(byText('תאריך חדש')).toBeExisting({ wait: 10000 });
      await tapLabel('סגירה');
      await expect(byText('תאריך חדש')).not.toBeDisplayed({ wait: 10000 });

      // «אזכרה»: заголовок «אזכרה» (не «תאריך חדש»).
      await homeDates();
      await tapLabel('הוספת תאריך חשוב');
      await tapText('אזכרה');
      await (await byLabel('שם הנפטר')).waitForExist({ timeout: 15000 });
      await expect(byText('אזכרה')).toBeExisting();
      expect(await shown(byText('תאריך חדש'))).toBe(false);
      await tapLabel('סגירה');

      // Правка: создать QA-дату на сегодня → карандаш → «עריכת תאריך».
      await addImportantDateToday(QA_DATE, isoDate(new Date()));
      await (await byLabel(`${QA_DATE}: פתיחה לעריכה`)).click();
      await expect(byText('עריכת תאריך')).toBeExisting({ wait: 15000 });
      expect(await shown(byText('תאריך חדש'))).toBe(false);
      await tapLabel('סגירה');
    } finally {
      // Уборка: удалить QA-дату (если создалась).
      expect(await tryDeleteDate(QA_DATE)).toBe(true);
    }
  });

  it('TX-01b Профиль → «הגדרות»: тумблер «תזכורות והתראות» (Figma 643:1031), старого «תזכורות במערכת» нет #32d78d #00542c25 @prod-safe', async () => {
    await openProfile();
    await scrollToText('הגדרות');
    await scrollToText('תזכורות והתראות');
    const labels = (await nodes()).map((n) => n.label).join('\n');
    expect(labels).toContain('תזכורות והתראות');
    expect(labels).toContain('כולל התראות ל: זמני תפילה');
    expect(labels).not.toContain('תזכורות במערכת');
  });

  it('TX-01c S-22: после «סיים תפילה» → «רשום שוב» окно «כל הכבוד!» с кнопкой «חזרה למסך ראשי» (не «המשך»); нажатие → главная (или окно достижения → главная), «סה״כ תפילות» +1 #32d78d #00542c25 S-22 AC1 AC2 @data', async function () {
    // Пишет в историю аккаунта ещё одну запись — только с QA_RECORD_PRAYER=1 (как RD-01c). Нужна молитва, уже записанная сегодня.
    if (!recordAllowed()) skipWith(this, 'QA_RECORD_PRAYER≠1 — запись молитвы не разрешена');
    await goHome();
    const today0 = await counter('תפילות היום');
    const total0 = await counter('סה״כ תפילות');
    await scrollToText('תפילות אחרונות').catch(() => {});
    const prayer = await newestRecentPrayer();
    if (!prayer || today0 === 0) skipWith(this, 'сегодня записей нет — нужна завершённая сегодня молитва (иначе окно времени)');

    await openCatalogPrayer(prayer!);
    if ((await tapFinish()) === 'already') await (await button(REPEAT_AGAIN)).click();
    await (await byText(FINISH_TITLE)).waitForExist({ timeout: 20000 });
    expect(await shown(button(BACK_HOME))).toBe(true);
    expect(await shown(button('המשך'))).toBe(false);
    await (await button(BACK_HOME)).click();
    // Если открылось окно достижения/уровня (S-23) — закрыть; затем главная.
    await driver.waitUntil(async () => {
      if (await shown(byTextContains('תפילות היום'))) return true;
      const close = await button('סגירה');
      if (await close.isExisting().catch(() => false)) await close.click().catch(() => {});
      return false;
    }, { timeout: 30000, interval: 1000, timeoutMsg: 'после «חזרה למסך ראשי» нет главной' });
    await goHome();
    expect(await counter('סה״כ תפילות')).toBe(total0 + 1);
  });
});
